// The worker programs are generated by a Node script before any test module loads them.
// @effect-diagnostics nodeBuiltinImport:off
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import type { TestProject } from "vitest/node";

const generate = () => {
  execFileSync(process.execPath, ["--experimental-strip-types", "build-worker.mjs"], {
    cwd: fileURLToPath(new URL("../..", import.meta.url)),
    stdio: "inherit",
  });
};

/** Regenerates `src/child-host/programs.ts` before the first run and before each watch rerun. */
export default (project: TestProject) => {
  generate();
  project.onTestsRerun(generate);
};
